diff --git a/server/Relay.Api/Controllers/HooksController.cs b/server/Relay.Api/Controllers/HooksController.cs
--- a/server/Relay.Api/Controllers/HooksController.cs
+++ b/server/Relay.Api/Controllers/HooksController.cs
@@ -96,8 +96,23 @@
             }
         }
 
-        var run = await _executor.RunFlowAsync(
-            webhook.FlowId, RunTrigger.Webhook, body, ct, idempotencyKey: idempotencyKey);
+        Run? run;
+        try
+        {
+            run = await _executor.RunFlowAsync(
+                webhook.FlowId, RunTrigger.Webhook, body, ct, idempotencyKey: idempotencyKey);
+        }
+        catch (DbUpdateException) when (idempotencyKey is not null)
+        {
+            // A concurrent delivery with the same key saved its run first: treat this
+            // one as the duplicate it is instead of surfacing a 500 to the sender.
+            _db.ChangeTracker.Clear();
+            var winner = await _db.Runs.AsNoTracking()
+                .FirstAsync(r => r.FlowId == webhook.FlowId && r.IdempotencyKey == idempotencyKey, ct);
+            await LogDelivery(webhook, true, WebhookDeliveryOutcome.Duplicate, winner.Id, "Deduplicated by idempotency key.", ct);
+            await _db.SaveChangesAsync(ct);
+            return Accepted(new { runId = winner.Id, status = winner.Status.ToString(), deduplicated = true });
+        }
 
         webhook.LastTriggeredAtUtc = _clock.UtcNow;
         await LogDelivery(webhook, true, WebhookDeliveryOutcome.Delivered, run!.Id, null, ct);
